  if($action==='login'&&isset($pdo)){
   $attempts=array_filter($_SESSION['staff_attempts']??[],fn($t)=>$t>time()-900);if(count($attempts)>=8)throw new InvalidArgumentException('Too many attempts. Try again in 15 minutes.');$attempts[]=time();$_SESSION['staff_attempts']=$attempts;
   $email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');$stmt=$pdo->prepare('SELECT * FROM staff WHERE email=?');$stmt->execute([$email]);$candidate=$stmt->fetch();
   $hash=$candidate['password_hash']??'$2y$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2uheWG/igi.';$verified=strlen($password)<=72&&password_verify($password,$hash);
   if(!$candidate||!$verified||!$candidate['active']||($candidate['locked_until']&&strtotime($candidate['locked_until'])>time())){
    if($candidate){$stmt=$pdo->prepare('UPDATE staff SET failed_attempts=failed_attempts+1,locked_until=CASE WHEN failed_attempts>=5 THEN DATE_ADD(NOW(),INTERVAL 15 MINUTE) ELSE locked_until END WHERE id=?');$stmt->execute([$candidate['id']]);}
    throw new InvalidArgumentException('Sign-in failed. Check your details or try again later.');
   }
   $stmt=$pdo->prepare('UPDATE staff SET failed_attempts=0,locked_until=NULL WHERE id=?');$stmt->execute([$candidate['id']]);session_regenerate_id(true);$_SESSION['staff_id']=(int)$candidate['id'];$_SESSION['staff_version']=(int)$candidate['session_version'];$_SESSION['staff_attempts']=[];staff_audit($pdo,(int)$candidate['id'],'Signed in','Staff portal');header('Location: admin.php');exit;
  }elseif($action!=='login'){
