 }catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(PDOException $e){error_log($e->getMessage());$error=$e->getCode()==='23000'?'This email address is already in use.':'The change could not be saved. Please try again.';}catch(Throwable $e){error_log($e->getMessage());$error='The request could not be completed. Please try again.';}
}
