 }
 if($view==='customers'){$stmt=$pdo->prepare('SELECT u.id,u.name,u.email,u.created_at,COUNT(b.id) AS bookings FROM users u LEFT JOIN bookings b ON b.user_id=u.id WHERE (u.name LIKE ? OR u.email LIKE ?) GROUP BY u.id ORDER BY u.id DESC LIMIT 200');$stmt->execute(['%'.$search.'%','%'.$search.'%']);$customers=$stmt->fetchAll();}
